231	    @Override
232	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
233	        Owner owner = this.clinicService.findOwnerById(ownerId);
234	        if (owner == null) {
235	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
236	        }
237	        HttpHeaders headers = new HttpHeaders();
238	        Pet pet = petMapper.toPet(petFieldsDto);
239	        owner.setId(ownerId);
240	        pet.setOwner(owner);
241	        pet.getType().setName(null);
242	        this.clinicService.savePet(pet);
243	        PetDto petDto = petMapper.toPetDto(pet);
244	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
245	            .buildAndExpand(pet.getId()).toUri());
246	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
247	    }
