249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Override
251	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
252	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
253	        if (currentOwner != null) {
254	            Pet currentPet = this.clinicService.findPetById(petId);
255	            if (currentPet != null) {
256	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
257	                currentPet.setName(petFieldsDto.getName());
258	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
259	                this.clinicService.savePet(currentPet);
260	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
261	            }
262	        }
263	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
264	    }
