267	    @Override
268	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
269	        HttpHeaders headers = new HttpHeaders();
270	        Visit visit = visitMapper.toVisit(visitFieldsDto);
