283	    @Override
284	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
285	        Owner owner = this.clinicService.findOwnerById(ownerId);
286	        if (owner != null) {
287	            Pet pet = owner.getPet(petId);
288	            if (pet != null) {
289	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
290	            }
291	        }
292	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
