294	
295	    /**
296	     * Counts how many existing owners share the given first and last name, compared
297	     * case-insensitively, at the moment before the new owner is persisted. The result is
298	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
299	     * stood when the owner was created rather than being recomputed on later reads.
300	     *
301	     * @param firstName the first name of the owner being created
302	     * @param lastName the last name of the owner being created
303	     * @return the number of pre-existing owners with the same first and last name
304	     */
305	    private int countNamesakes(String firstName, String lastName) {
306	        String first = firstName == null ? "" : firstName;
307	        String last = lastName == null ? "" : lastName;
308	        return (int) this.clinicService.findAllOwners().stream()
309	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
310	                && last.equalsIgnoreCase(existing.getLastName()))
311	            .count();
312	    }
313	
314	    /**
315	     * Builds the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'} where
316	     * {@code REGION} is the region code derived from the owner's postcode (see {@link #deriveRegion})
317	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
318	     * normalized telephone concatenated with the last name. For example an owner in the NSW postcode
319	     * range gets a code such as {@code 'NSW-3F2A1B9C'}.
320	     *
321	     * @param owner the owner being created, whose postcode, city and last name feed the code
322	     * @param normalizedTelephone the owner's E.164-normalized telephone
323	     * @return the assigned customer code
324	     */
325	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
326	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
327	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
328	        String hash8 = sha256Hex8(normalizedTelephone + lastName);
329	        return region + "-" + hash8;
330	    }
331	
332	    /**
333	     * Derives an owner's region code, preferring the postcode: the region whose {@link #REGION_POSTCODES}
334	     * range contains the (4-digit) postcode is returned, falling back to the fixed {@link #CITY_REGION}
335	     * city table when the postcode is absent or in no known range, and finally to {@code "UNKNOWN"}.
336	     *
337	     * @param postcode the owner's postcode, may be {@code null}
338	     * @param city the owner's city, used to resolve the region when the postcode does not
339	     * @return the canonical region string, or {@code "UNKNOWN"} when neither source resolves a region
340	     */
341	    private String deriveRegion(String postcode, String city) {
342	        if (postcode != null) {
343	            try {
344	                int value = Integer.parseInt(postcode.trim());
345	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
346	                    int[] range = entry.getValue();
347	                    if (value >= range[0] && value <= range[1]) {
348	                        return entry.getKey();
349	                    }
350	                }
351	            } catch (NumberFormatException ex) {
352	                // Not a numeric postcode; fall back to the city table below.
353	            }
354	        }
355	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
356	    }
357	
358	    /**
359	     * Computes the first 8 upper-case hex characters (the first 4 bytes) of the SHA-256 digest of the
360	     * given input's UTF-8 bytes.
361	     *
362	     * @param input the string to hash
363	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
364	     */
365	    private String sha256Hex8(String input) {
366	        try {
367	            byte[] digest = MessageDigest.getInstance("SHA-256")
368	                .digest(input.getBytes(StandardCharsets.UTF_8));
369	            StringBuilder hex = new StringBuilder();
370	            for (int i = 0; i < 4; i++) {
371	                hex.append(String.format("%02X", digest[i]));
372	            }
373	            return hex.toString();
374	        } catch (NoSuchAlgorithmException ex) {
375	            throw new IllegalStateException("SHA-256 not available", ex);
376	        }
377	    }
378	
379	    /**
380	     * Rejects an owner payload that is missing or blank in any of the required fields
381	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
382	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
383	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
384	     * guard enforces the rule uniformly for every required field.
385	     *
386	     * @param ownerFieldsDto the submitted owner payload
387	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
388	     */
389	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
390	        List<String> invalidFields = new ArrayList<>();
391	        if (isBlank(ownerFieldsDto.getFirstName())) {
392	            invalidFields.add("firstName");
393	        }
394	        if (isBlank(ownerFieldsDto.getLastName())) {
395	            invalidFields.add("lastName");
396	        }
397	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
398	            invalidFields.add("address");
399	        }
400	        if (isBlank(ownerFieldsDto.getCity())) {
401	            invalidFields.add("city");
402	        }
403	        if (isBlank(ownerFieldsDto.getTelephone())) {
404	            invalidFields.add("telephone");
405	        }
406	        if (!invalidFields.isEmpty()) {
407	            throw new InvalidOwnerFieldsException(invalidFields);
408	        }
409	    }
410	
411	    private boolean isBlank(String value) {
412	        return value == null || value.isBlank();
413	    }
414	
415	    /**
416	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
417	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
418	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
419	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
420	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
421	     * and returned exactly as given.
422	     *
423	     * @param postcode the submitted postcode, may be {@code null} when absent
424	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
425	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
426	     */
427	    private void validatePostcode(String postcode, String city) {
428	        if (postcode == null) {
429	            return;
430	        }
431	        if (!postcode.matches("[0-9]{4}")) {
432	            throw new InvalidOwnerFieldsException(List.of("postcode"));
433	        }
434	        String region = city == null ? null : CITY_REGION.get(city);
435	        if (region == null) {
436	            return;
437	        }
438	        int[] range = REGION_POSTCODES.get(region);
439	        int value = Integer.parseInt(postcode);
440	        if (value < range[0] || value > range[1]) {
441	            throw new InvalidOwnerFieldsException(List.of("postcode"));
442	        }
443	    }
444	
445	    /**
446	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
447	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
448	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
449	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
450	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
451	     *
452	     * @param telephone the raw telephone value from the submitted owner payload
453	     * @return the normalized E.164 telephone number
454	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
455	     */
456	    private String normalizeTelephone(String telephone) {
457	        String raw = telephone == null ? "" : telephone.strip();
458	        boolean hasCountryCode = raw.startsWith("+");
459	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
460	        String digits;
461	        if (hasCountryCode) {
462	            digits = cleaned.substring(1);
463	        } else {
464	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
465	            digits = "61" + national;
466	        }
467	        if (!digits.matches("[0-9]{8,15}")) {
468	            throw new InvalidOwnerFieldsException(List.of("telephone"));
469	        }
470	        validateNationalNumberLength(digits);
471	        return "+" + digits;
472	    }
473	
474	    /**
475	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
476	     * country calling code) has the exact length required for that country. The country code is matched
477	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
478	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
479	     *
480	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
481	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
482	     */
483	    private void validateNationalNumberLength(String digits) {
484	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
485	            String countryCode = entry.getKey();
486	            if (digits.startsWith(countryCode)) {
487	                int nationalLength = digits.length() - countryCode.length();
488	                if (nationalLength != entry.getValue()) {
489	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
490	                }
491	                return;
492	            }
493	        }
494	    }
495	
496	    /**
497	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
498	     * returning {@code null} when the value cannot form a valid E.164 number.
499	     *
500	     * @param telephone an existing owner's stored telephone value
501	     * @return the E.164 form, or {@code null} if it cannot be normalized
502	     */
503	    private String toE164OrNull(String telephone) {
504	        try {
505	            return normalizeTelephone(telephone);
506	        } catch (InvalidOwnerFieldsException ex) {
507	            return null;
508	        }
509	    }
510	
511	    /**
512	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
513	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
514	     * accepted value is trimmed and lower-cased before it is stored and returned.
515	     *
516	     * @param email the raw email value from the submitted owner payload, may be {@code null}
517	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
518	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
519	     *         or if its domain is on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS})
520	     */
521	    private String normalizeEmail(String email) {
522	        if (email == null) {
523	            return null;
524	        }
525	        String trimmed = email.strip();
526	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
527	            throw new InvalidOwnerFieldsException(List.of("email"));
528	        }
529	        String normalized = trimmed.toLowerCase(Locale.ROOT);
530	        String domain = normalized.substring(normalized.indexOf('@') + 1);
531	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
532	            throw new InvalidOwnerFieldsException(List.of("email"));
533	        }
534	        return normalized;
535	    }
536	
537	    /**
538	     * Rejects creating an owner that would be a second member of an existing household. The household
539	     * is keyed on {@code (lastName, postcode)} through the deterministic {@link #householdId}, so any
540	     * existing owner carrying the same {@code householdId} makes the owner being created a household
541	     * duplicate. Such an owner is rejected with a 409, <em>unless</em> the request opts into
542	     * {@code sharesHousehold}: a declared household member deliberately bypasses this block and is
543	     * created as an additional member of the household.
544	     *
545	     * @param owner the owner being created, whose computed household id is matched
546	     * @param sharesHousehold whether the request declared the owner a shared-household member
547	     * @throws DuplicateOwnerIdentityException if another owner already belongs to the same household
548	     */
549	    private void rejectDuplicateIdentity(Owner owner, boolean sharesHousehold) {
550	        if (sharesHousehold) {
551	            return;
552	        }
553	        String householdId = owner.getHouseholdId();
554	        boolean duplicate = householdId != null && this.clinicService.findAllOwners().stream()
555	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
556	        if (duplicate) {
557	            throw new DuplicateOwnerIdentityException(householdId);
558	        }
559	    }
560	
561	    /**
562	     * Flags a soft ("possible") duplicate on the owner being created. Unlike a hard duplicate (which is
563	     * rejected outright by {@link #rejectDuplicateIdentity}), a soft duplicate is still created: it is an
564	     * owner that is not a hard duplicate but shares an existing owner's last name (compared
565	     * case-insensitively, see {@link #normalizeForComparison}) and postcode while carrying a <em>different</em>
566	     * telephone. When such an existing owner is found, {@code possibleDuplicate} is set {@code true} and
567	     * {@code possibleDuplicateOf} is set to that owner's id (the earliest by id when several match); otherwise
568	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays {@code null}. Both values
569	     * are snapshotted on the owner so they reflect the population as it stood when the owner was created.
570	     *
571	     * <p>A declared household member (a request that set {@code sharesHousehold} to bypass the household
572	     * duplicate block) is never a <em>suspected</em> duplicate: it is knowingly created as another member
573	     * of the household, so {@code possibleDuplicate} is left {@code false} and {@code possibleDuplicateOf}
574	     * {@code null} without consulting the existing population.
575	     *
576	     * @param owner the owner being created, whose last name and postcode are matched
577	     * @param normalizedTelephone the E.164 telephone of the owner being created
578	     * @param sharesHousehold whether the request declared the owner a shared-household member
579	     */
580	    private void assignPossibleDuplicate(Owner owner, String normalizedTelephone, boolean sharesHousehold) {
581	        if (sharesHousehold) {
582	            owner.setPossibleDuplicateOf(null);
583	            owner.setPossibleDuplicate(false);
584	            return;
585	        }
586	        String postcode = owner.getPostcode();
587	        Integer matchId = null;
588	        if (postcode != null) {
589	            String lastName = normalizeForComparison(owner.getLastName());
590	            for (Owner existing : this.clinicService.findAllOwners()) {
591	                if (postcode.equals(existing.getPostcode())
592	                    && lastName.equals(normalizeForComparison(existing.getLastName()))
593	                    && !normalizedTelephone.equals(toE164OrNull(existing.getTelephone()))
594	                    && existing.getId() != null
595	                    && (matchId == null || existing.getId() < matchId)) {
596	                    matchId = existing.getId();
597	                }
598	            }
599	        }
600	        owner.setPossibleDuplicateOf(matchId);
601	        owner.setPossibleDuplicate(matchId != null);
602	    }
603	
604	    /**
605	     * The maximum number of owners a single city may contain. Once a city already holds this many
606	     * owners, creating another owner in that city is rejected.
607	     */
608	    private static final int MAX_OWNERS_PER_CITY = 50;
609	
610	    /**
611	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
612	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
613	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
614	     * counting used elsewhere.
615	     *
616	     * @param city the city of the owner being created
617	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
618	     */
619	    /**
620	     * The maximum number of owners that may be registered on a single day. Once this many owners
621	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
622	     */
623	    private static final int MAX_OWNERS_PER_DAY = 100;
624	
625	    /**
626	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
627	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
628	     * registration date of the owner being created.
629	     *
630	     * @param registrationDate the registration date of the owner being created
631	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
632	     */
633	    /**
634	     * Rolls an effective registration date forward onto a business day. A registration date must fall
635	     * on a weekday: when the supplied or defaulted date is a Saturday or Sunday it is rolled forward to
636	     * the next Monday and that adjusted date becomes the owner's {@code registrationDate}. A weekday date
637	     * is returned unchanged. Every value derived from the registration date (the daily create-limit
638	     * count, the membership number's year segment, and so on) uses this adjusted date.
639	     *
640	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
641	     * @return the same date if it is a weekday, otherwise the following Monday
642	     */
643	    /**
644	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server's
645	     * current date. A registration date is not permitted to lie in the future; a {@code null} date
646	     * (defaulted to the server date) and any date on or before today are accepted. The check runs
647	     * against the date exactly as supplied, before it is rolled forward onto a business day.
648	     *
649	     * @param registrationDate the registration date supplied in the request, may be {@code null}
650	     * @throws FutureRegistrationDateException if the supplied date is after the server date
651	     */
652	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
653	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
654	            throw new FutureRegistrationDateException(registrationDate);
655	        }
656	    }
657	
658	    private LocalDate rollToBusinessDay(LocalDate date) {
659	        DayOfWeek day = date.getDayOfWeek();
660	        if (day == DayOfWeek.SATURDAY) {
661	            return date.plusDays(2);
662	        }
663	        if (day == DayOfWeek.SUNDAY) {
664	            return date.plusDays(1);
665	        }
666	        return date;
667	    }
668	
669	    private void rejectDailyLimitReached(LocalDate registrationDate) {
670	        long ownersToday = this.clinicService.findAllOwners().stream()
671	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
672	            .count();
673	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
674	            throw new DailyOwnerLimitExceededException(registrationDate);
675	        }
676	    }
677	
678	    /**
679	     * The number of owners that must already share a {@code registrationDate} before a newly created
680	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
681	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
682	     */
683	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
684	
685	    /**
686	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
687	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
688	     * the same registration date at the time this owner is created. Existing owners are counted by their
689	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
690	     * daily create-limit accumulation.
691	     *
692	     * @param registrationDate the registration date of the owner being created
693	     * @return {@code true} if the day already holds more than the threshold number of owners
694	     */
695	    private boolean isBulkSignupDay(LocalDate registrationDate) {
696	        long ownersToday = this.clinicService.findAllOwners().stream()
697	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
698	            .count();
699	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
700	    }
701	
702	    private void rejectCityAtCapacity(String city) {
703	        String normalizedCity = normalizeForComparison(city);
704	        long ownersInCity = this.clinicService.findAllOwners().stream()
705	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
706	            .count();
707	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
708	            throw new OwnerCityCapacityExceededException(city);
709	        }
710	    }
711	
712	    /**
713	     * Counts how many owners belong to the household the owner being created has just been assigned to,
714	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
715	     * given identifier; the owner being created is added on because it is counted before being persisted.
716	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
717	     * household of one. The value is snapshotted on the owner.
718	     *
719	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
720	     * @return the number of household members, including the owner being created
721	     */
722	    private int countHousehold(String householdId) {
723	        if (householdId == null) {
724	            return 1;
725	        }
726	        long existing = this.clinicService.findAllOwners().stream()
727	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
728	            .count();
729	        return (int) existing + 1;
730	    }
731	
732	    /**
733	     * Derives the deterministic household identifier for a given last name and postcode: the first 12
734	     * hex characters of the SHA-256 digest of {@code '<normalizedLastName>|<postcode>'}, where the last
735	     * name is normalized for case- and whitespace-insensitive comparison (see
736	     * {@link #normalizeForComparison}) and a {@code null} postcode contributes an empty segment. Every
737	     * owner that shares a last name and postcode therefore resolves to the exact same identifier,
738	     * regardless of creation order, making them members of one household.
739	     *
740	     * @param lastName the owner's last name
741	     * @param postcode the owner's postcode, may be {@code null}
742	     * @return the deterministic household identifier
743	     */
744	    private String householdId(String lastName, String postcode) {
745	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
746	        try {
747	            byte[] digest = MessageDigest.getInstance("SHA-256")
748	                .digest(key.getBytes(StandardCharsets.UTF_8));
749	            StringBuilder hex = new StringBuilder();
750	            for (int i = 0; i < 6; i++) {
751	                hex.append(String.format("%02x", digest[i]));
752	            }
753	            return hex.toString();
754	        } catch (NoSuchAlgorithmException ex) {
755	            throw new IllegalStateException("SHA-256 not available", ex);
756	        }
757	    }
758	
759	    /**
760	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
761	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
762	     * result is lower-cased. A {@code null} value normalizes to the empty string.
763	     *
764	     * @param value the value to normalize, may be {@code null}
765	     * @return the normalized value
766	     */
767	    private String normalizeForComparison(String value) {
768	        if (value == null) {
769	            return "";
770	        }
771	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
772	    }
773	
774	    /**
775	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
776	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
777	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
778	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
779	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
780	     * that is stored, returned, and used for every address comparison (household duplicate detection
781	     * and the shared household id).
782	     *
783	     * @param address the raw address value from the submitted owner payload, may be {@code null}
784	     * @return the normalized address
785	     */
786	    private String normalizeAddress(String address) {
787	        if (address == null) {
788	            return "";
789	        }
790	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
791	        if (collapsed.isEmpty()) {
792	            return "";
793	        }
794	        String[] tokens = collapsed.split(" ");
795	        StringBuilder normalized = new StringBuilder();
796	        for (int i = 0; i < tokens.length; i++) {
797	            if (i > 0) {
798	                normalized.append(' ');
799	            }
800	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
801	        }
802	        return normalized.toString();
803	    }
804	}
